function _create_postItemsSoupAstBody() {
  return zod
    .object({
      asf: zod
        .unknown()
        .optional()
        .describe(
          'Filters applied to agent sessions (wire key `asf`). An empty or\nomitted filter returns \*\*no\*\* agent sessions: they are opt-in, so the\ncaller must send `inc`, an id, or an owner to get any.'
        ),
      calf: zod
        .unknown()
        .optional()
        .describe('filters applied to canonical calendar events'),
      callf: zod
        .unknown()
        .optional()
        .describe('the filters that should be applied to the call entity'),
      ccf: zod
        .unknown()
        .optional()
        .describe(
          "Filters applied to the crm_company entity (wire key `ccf`).\nEmpty\/omitted = team's full visible list."
        ),
      cf: zod
        .unknown()
        .optional()
        .describe('the filters that should be applied to the chat entity'),
      chanf: zod
        .unknown()
        .optional()
        .describe('the filters that should be applied to the channel entity'),
      crma: zod
        .union([
          zod.null(),
          zod
            .union([
              zod
                .object({
                  company: zod
                    .uuid()
                    .describe(
                      'Items associated with the company or with any of its contacts.'
                    ),
                })
                .describe(
                  'Items associated with the company or with any of its contacts.'
                ),
              zod
                .object({
                  contact: zod
                    .uuid()
                    .describe('Items associated with the contact.'),
                })
                .describe('Items associated with the contact.'),
              zod
                .enum(['activity'])
                .describe(
                  'Activity across visible CRM-enabled teams, excluding hidden records.'
                ),
            ])
            .describe('The CRM record an association filter names.'),
        ])
        .optional(),
      crmf: zod
        .unknown()
        .optional()
        .describe(
          'Opt-in filters for viewer-accessible CRM contacts (wire key `crmf`).'
        ),
      cthf: zod
        .unknown()
        .optional()
        .describe(
          'the filters that should be applied to the channel-thread entity'
        ),
      df: zod
        .unknown()
        .optional()
        .describe('the filters that should be applied to the document entity'),
      eca: zod
        .array(zod.string())
        .optional()
        .describe(
          'CRM-scoped address filter (wire key: `eca`). Symmetric counterpart\nto `ecd` for fully-qualified email addresses.'
        ),
      ecd: zod
        .array(zod.string())
        .optional()
        .describe(
          'CRM-scoped domain filter (wire key: `ecd`). Parallel to the\nfreeform `ef` AST. Expanded by the router into an any-direction\nOR sub-tree AND-merged into `ef`, plus a `CrmScope` tag stamped\non the resulting [`item_filters::ast::EmailFilterAst::crm_scope`].\nDrives the per-team CRM authorization pre-check and candidate-set\nwidening downstream. Mutually exclusive with `eca`.'
        ),
      ef: zod
        .unknown()
        .optional()
        .describe(
          'the filters that should be applied to the email entity (raw AST\ntree only; CRM scope is carried by the `ecd` \/ `eca` sibling\nfields). On this endpoint the email filter stays a bare tree,\nunlike the materialized [`EntityFilterAst`] used for cursors.'
        ),
      favorites_only: zod
        .boolean()
        .nullish()
        .describe(
          "Restrict to the authenticated viewer's favorites before pagination when true."
        ),
      fef: zod
        .unknown()
        .optional()
        .describe(
          'the filters that should be applied to foreign entity records'
        ),
      ghprf: zod
        .unknown()
        .optional()
        .describe(
          'the filters that should be applied to GitHub pull request records, on top of `fef`'
        ),
      if: zod
        .unknown()
        .optional()
        .describe(
          'Filters applied to initiatives (wire key `if`). Opt-in like agent\nsessions: an omitted filter returns no initiatives, and any literal,\na notification state included, opts them in.'
        ),
      pf: zod
        .unknown()
        .optional()
        .describe('the filters that should be applied to the project entity'),
      propf: zod
        .unknown()
        .optional()
        .describe(
          'the filters that should be applied based on entity properties'
        ),
    })
    .describe('Wire-format entity filter AST accepted by soup AST endpoints.')
    .and(
      zod
        .object({
          expand: zod
            .boolean()
            .nullish()
            .describe('Whether to expand projects. Defaults to true.'),
          limit: zod
            .number()
            .min(postItemsSoupAstBodyLimitMin)
            .nullish()
            .describe(
              'Limit the number of items returned. Defaults to 20. Max 500.'
            ),
          sort_direction: zod
            .union([
              zod.null(),
              zod
                .enum(['asc', 'desc'])
                .describe(
                  'Sort direction accepted by non-grouped soup API endpoints.'
                ),
            ])
            .optional(),
          sort_method: zod
            .union([
              zod.null(),
              zod
                .enum([
                  'viewed_at',
                  'created_at',
                  'updated_at',
                  'viewed_updated',
                  'frecency',
                  'touched_by_me',
                  'notified_at',
                  'property',
                ])
                .describe(
                  'Sort options accepted by non-grouped soup API endpoints.'
                ),
            ])
            .optional(),
          sort_property_definition_id: zod
            .uuid()
            .nullish()
            .describe(
              'Property definition selected for numeric property sorting.'
            ),
        })
        .describe('Query parameters shared by soup endpoints.')
    )
    .and(
      zod.object({
        emailView: zod
          .string()
          .optional()
          .describe('the view of specific emails to display'),
      })
    )
    .describe('Request body for the AST soup endpoint.');
}
